"""Import images generated by hand in the Google AI Studio web app (free, no API billing).

How to generate (per model, per prompt):
  1. https://aistudio.google.com -> choose the model (Gemini 2.5 Flash Image / Gemini 3.1 Flash Image Preview)
  2. Set aspect ratio 1:1. Paste the exact prompt from prompt_sheet.html. Run ONCE, keep the first image.
  3. Download it as  q1/manual/<g25|g31>/<PROMPT_ID>.png   (e.g. q1/manual/g25/P01.png)
  4. Take one screenshot per model session showing the model name + a prompt + result -> q1/manual/screens/
Then run:  python q1/import_manual.py
"""
import json, pathlib, datetime, sys
from PIL import Image

HERE = pathlib.Path(__file__).parent
sys.path.insert(0, str(HERE))
from generate import build_prompt, MODELS

IDS = {"g25": "gemini-2.5-flash-image", "g31": "gemini-3.1-flash-image-preview"}
spec = json.loads((HERE / "prompts.json").read_text(encoding="utf-8"))
log = HERE / "generation_log.jsonl"
n = 0
for short, mid in IDS.items():
    for p in spec["prompts"]:
        src = next((f for ext in ("png", "jpg", "jpeg", "webp") for f in [HERE / "manual" / short / f"{p['id']}.{ext}"] if f.exists()), None)
        dst = HERE / "images" / f"{p['id']}_{short}.png"
        if not src or dst.exists():
            continue
        Image.open(src).convert("RGB").save(dst)
        ts = datetime.datetime.fromtimestamp(src.stat().st_mtime, datetime.timezone.utc).isoformat()
        rec = {"prompt_id": p["id"], "company": "Google", "model_name": MODELS[mid]["name"], "model_id": mid,
               "prompt": build_prompt(spec, p), "attempt": 1, "timestamp_utc": ts, "platform": "Google AI Studio (web app)",
               "status": "ok", "request_id": None, "settings": {"aspectRatio": "1:1", "outputs": 1, "first output kept": True},
               "latency_s": None, "file": f"images/{dst.name}", "source_file": str(src.relative_to(HERE))}
        with log.open("a", encoding="utf-8") as f:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")
        n += 1
print(f"imported {n} images")
